export const NEATENSTEIN_DYNAMIC_LIGHT_RADIUS_CELLS = 6;

/**
 * Distance in cells just beyond {@link NEATENSTEIN_CONTACT_RANGE_CELLS} used
 * to place an enemy outside contact-damage range for out-of-range testing.
 */
export const NEATENSTEIN_TEST_ENEMY_BEYOND_CONTACT_RANGE_CELLS =
  NEATENSTEIN_CONTACT_RANGE_CELLS + 1;

/**
 * Distance in cells from the player to a test enemy placed directly on the
 * bolt path.
 *
 * Small enough to sit before the nearest wall from the central spawn point
 * when firing along the +X axis, so the bolt reliably hits the enemy first.
 */
export const NEATENSTEIN_TEST_ENEMY_NEAR_DISTANCE_CELLS = 2;

/**
 * Perpendicular offset in cells used to place a test enemy just outside the
 * bolt hit radius.
 *
 * The value is larger than {@link NEATENSTEIN_BOLT_HIT_RADIUS_CELLS} so the
 * enemy is missed even though it shares the same forward distance as a hit
 * enemy.
 */
export const NEATENSTEIN_TEST_ENEMY_OFF_BOLT_OFFSET_CELLS = 0.5;

/**
 * Travel speed of an enemy plasma bolt in world cells per second.
 *
 * Matches the player bolt speed so enemy projectiles feel responsive and
 * consistent with the existing combat model.
 */
export const NEATENSTEIN_ENEMY_BOLT_SPEED_CELLS_PER_SECOND = 36;

/**
 * Damage applied to the player by a single enemy bolt hit.
 *
 * Set to 10 (= 10% of the player's 100 maxHealth) so each hit is meaningful
 * but not instantly lethal. Reuses the existing contact i-frame window
 * ({@link NEATENSTEIN_CONTACT_IFRAME_MS}) — no separate enemy-bolt i-frame.
 */
export const NEATENSTEIN_ENEMY_BOLT_DAMAGE = 10;

/**
 * Maximum lifetime of an enemy plasma bolt in milliseconds.
 *
 * Caps the distance an enemy bolt can travel and prevents lingering bolts
 * in the simulation.
 */
export const NEATENSTEIN_ENEMY_BOLT_LIFETIME_MS = 2000;

/**
 * Maximum distance an enemy plasma bolt can travel in world cells.
 *
 * Bolts expire once they travel this far, matching the player bolt range.
 */
export const NEATENSTEIN_ENEMY_BOLT_MAX_RANGE_CELLS = 30;

/**
 * Radius in world cells for enemy-bolt/player proximity collision.
 *
 * When an enemy bolt gets within this distance of the player, it registers a
 * hit and applies damage.
 */
export const NEATENSTEIN_ENEMY_BOLT_HIT_RADIUS_CELLS = 0.5;
/**
 * Host-side input router for the Neatenstein neon raycasting demo.
 *
 * The router attaches to a DOM target, accumulates keyboard, mouse, touch, and
 * pointer-lock input, and produces a consumable {@link InputSnapshot} each
 * simulation tick.
 *
 * Controls.ts owns low-level modality bindings. This module centralizes the
 * authoritative, clone-safe input state that is forwarded to the worker tier.
 *
 * @module
 */

import {
  NEATENSTEIN_DASH_KEY,
  NEATENSTEIN_FIRE_KEY,
  NEATENSTEIN_KEY_MAP_MOVEMENT,
} from './game/constants';
import {
  bindKeyboardLightToggle,
  bindKeyboardLook,
  bindMouseFire,
  bindMouseLook,
  bindPointerLock,
  bindTouchLook,
  type BindingDetach,
  type LookDelta,
  type TouchActiveCallback,
} from './game/controls';

/** Convenience type alias for a keyboard handler reference. */
type KeyboardEventHandler = (event: KeyboardEvent) => void;

/** Convenience type alias for no-argument DOM event handlers. */
type VoidDomEventHandler = () => void;

/**
 * Snapshot of raw player input at a single point in time.
 *
 * The snapshot is intentionally clone-safe so it can be passed across the
 * worker boundary via `postMessage` without losing information.
 */
export interface InputSnapshot {
  /** Milliseconds since epoch when the snapshot was captured. */
  timestamp: number;

  /** Directional movement intent from movement keys. */
  movement: {
    /** True while the forward key is held. */
    forward: boolean;
    /** True while the backward key is held. */
    backward: boolean;
    /** True while the strafe-left key is held. */
    left: boolean;
    /** True while the strafe-right key is held. */
    right: boolean;
  };

  /**
   * Accumulated orientation change since the last snapshot, in radians.
   *
   * Mouse, touch, and keyboard look deltas are consumed when the snapshot is
   * read so the same physical movement is never applied twice.
   */
  look: {
    /** Horizontal rotation delta. */
    yawDelta: number;
    /** Vertical rotation delta. */
    pitchDelta: number;
  };

  /** Current touch drag-to-look state for mobile fallback. */
  touch: {
    /** True while at least one active touch is being tracked. */
    active: boolean;
    /** Horizontal yaw delta from the active touch drag. */
    yawDelta: number;
    /** Vertical pitch delta from the active touch drag. */
    pitchDelta: number;
  };

  /** Whether the pointer is currently locked to the attached target. */
  pointerLocked: boolean;

  /**
   * Primary fire input for the current snapshot.
   *
   * Mouse clicks and keyboard fire presses are latched until consumed so quick
   * taps between render frames are not lost.
   */
  fire: boolean;

  /**
   * Dash input for the current snapshot.
   *
   * Dash presses are latched until consumed so quick taps between render frames
   * are not lost.
   */
  dash: boolean;

  /**
   * Dynamic light toggle input for the current snapshot.
   *
   * Toggle presses are latched until consumed so quick taps between render
   * frames are not lost.
   */
  lightToggle: boolean;
}

/** Detaches all event listeners installed by the router. */
export type InputRouterDetach = () => void;

/**
 * Public surface of a host input router.
 */
export interface InputRouter {
  /**
   * Attach input listeners to a DOM target.
   *
   * @param target - Element that owns pointer lock and receives mouse/touch
   *   events. Keyboard events are read from `window`.
   * @returns A detach function for this attachment.
   * @throws {Error} If the router is already attached.
   */
  attach(target: HTMLElement): InputRouterDetach;

  /** Remove all installed listeners and reset transient input state. */
  detach(): void;

  /**
   * Capture and reset the current input snapshot.
   *
   * Calling this consumes pending mouse, touch, keyboard-look, fire, and dash
   * deltas/actions.
   *
   * @returns A clone-safe input snapshot.
   */
  getSnapshot(): InputSnapshot;
}

/**
 * Create a host-side input router.
 *
 * @returns A new {@link InputRouter} instance.
 */
export function createInputRouter(): InputRouter {
  let attachedTarget: HTMLElement | null = null;
  let attachmentId = 0;

  const keyStates: Record<string, boolean> = {};

  let mouseYawDelta = 0;
  let mousePitchDelta = 0;
  let keyboardYawDelta = 0;
  let keyboardPitchDelta = 0;
  let touchYawDelta = 0;
  let touchPitchDelta = 0;

  let pendingFire = false;
  let pendingDash = false;
  let pendingLightToggle = false;
  let touchActive = false;

  let keyDownHandler: KeyboardEventHandler | null = null;
  let keyUpHandler: KeyboardEventHandler | null = null;
  let windowBlurHandler: VoidDomEventHandler | null = null;
  let visibilityChangeHandler: VoidDomEventHandler | null = null;

  let pointerLockDetach: BindingDetach | null = null;
  let mouseFireDetach: BindingDetach | null = null;
  let mouseLookDetach: BindingDetach | null = null;
  let keyboardLookDetach: BindingDetach | null = null;
  let keyboardLightToggleDetach: BindingDetach | null = null;
  let touchLookDetach: BindingDetach | null = null;

  /**
   * Return whether a key code is one of the router's action keys.
   *
   * @param code - KeyboardEvent.code value.
   * @returns Whether the code represents a one-shot action.
   */
  function isActionKey(code: string): boolean {
    return code === NEATENSTEIN_FIRE_KEY || code === NEATENSTEIN_DASH_KEY;
  }

  /**
   * Update movement/action key states from a keyboard event.
   *
   * Fire and dash keydown events are latched on first press so quick taps
   * between snapshots are preserved.
   *
   * @param event - Keyboard event.
   * @param pressed - `true` for keydown, `false` for keyup.
   */
  function updateKeyState(event: KeyboardEvent, pressed: boolean): void {
    const wasPressed = keyStates[event.code] === true;
    keyStates[event.code] = pressed;

    if (pressed && !wasPressed) {
      if (event.code === NEATENSTEIN_FIRE_KEY) {
        pendingFire = true;
      }

      if (event.code === NEATENSTEIN_DASH_KEY) {
        pendingDash = true;
      }
    }

    // Prevent common gameplay keys from scrolling or activating page controls.
    if (
      isActionKey(event.code) ||
      (
        Object.values(NEATENSTEIN_KEY_MAP_MOVEMENT) as readonly string[]
      ).includes(event.code)
    ) {
      event.preventDefault();
    }
  }

  /**
   * Accumulate keyboard look deltas.
   *
   * @param delta - Look delta emitted by the keyboard binding.
   */
  function onKeyboardLook(delta: LookDelta): void {
    keyboardYawDelta += delta.yawDelta;
    keyboardPitchDelta += delta.pitchDelta;
  }

  /**
   * Accumulate mouse look deltas.
   *
   * @param delta - Look delta emitted by the mouse binding.
   */
  function onMouseLook(delta: LookDelta): void {
    mouseYawDelta += delta.yawDelta;
    mousePitchDelta += delta.pitchDelta;
  }

  /**
   * Accumulate touch look deltas.
   *
   * @param delta - Look delta emitted by the touch binding.
   */
  function onTouchLook(delta: LookDelta): void {
    touchYawDelta += delta.yawDelta;
    touchPitchDelta += delta.pitchDelta;
  }

  /**
   * Track whether touch look input is active.
   *
   * @param active - Whether a touch gesture is currently active.
   */
  const onTouchActive: TouchActiveCallback = (active): void => {
    touchActive = active;
  };

  /**
   * Reset tracked key state only.
   *
   * Useful when the window loses focus and keyup events may not be delivered.
   */
  function resetKeyState(): void {
    for (const code of Object.keys(keyStates)) {
      delete keyStates[code];
    }
  }

  /**
   * Reset transient input state without touching installed listeners.
   */
  function resetInputState(): void {
    resetKeyState();
    mouseYawDelta = 0;
    mousePitchDelta = 0;
    keyboardYawDelta = 0;
    keyboardPitchDelta = 0;
    touchYawDelta = 0;
    touchPitchDelta = 0;
    pendingFire = false;
    pendingDash = false;
    pendingLightToggle = false;
    touchActive = false;
  }

  /**
   * Bind keyboard and lifecycle listeners.
   */
  function bindEventListeners(): void {
    keyDownHandler = (event) => updateKeyState(event, true);
    keyUpHandler = (event) => updateKeyState(event, false);
    windowBlurHandler = () => resetKeyState();
    visibilityChangeHandler = () => {
      if (document.visibilityState !== 'visible') {
        resetKeyState();
      }
    };

    window.addEventListener('keydown', keyDownHandler);
    window.addEventListener('keyup', keyUpHandler);
    window.addEventListener('blur', windowBlurHandler);
    document.addEventListener('visibilitychange', visibilityChangeHandler);
  }

  /**
   * Bind pointer, mouse, keyboard-look, and touch-look listeners.
   *
   * @param target - Attached DOM target.
   */
  function bindLookListeners(target: HTMLElement): void {
    mouseLookDetach = bindMouseLook(target, onMouseLook);
    keyboardLookDetach = bindKeyboardLook(target, onKeyboardLook);
    touchLookDetach = bindTouchLook(target, onTouchLook, onTouchActive);
  }

  /**
   * Remove keyboard and lifecycle listeners.
   */
  function removeMovementListeners(): void {
    window.removeEventListener('keydown', keyDownHandler as EventListener);
    window.removeEventListener('keyup', keyUpHandler as EventListener);
    window.removeEventListener('blur', windowBlurHandler as EventListener);
    document.removeEventListener(
      'visibilitychange',
      visibilityChangeHandler as EventListener,
    );

    keyDownHandler = null;
    keyUpHandler = null;
    windowBlurHandler = null;
    visibilityChangeHandler = null;
  }

  /**
   * Remove look listeners.
   */
  function removeLookListeners(): void {
    mouseLookDetach?.();
    mouseLookDetach = null;

    keyboardLookDetach?.();
    keyboardLookDetach = null;

    touchLookDetach?.();
    touchLookDetach = null;
  }

  /**
   * Detach the current attachment if the token matches.
   *
   * @param token - Attachment token captured by the detach closure.
   */
  function detachByToken(token: number): void {
    if (attachedTarget === null || token !== attachmentId) {
      return;
    }

    pointerLockDetach?.();
    pointerLockDetach = null;

    mouseFireDetach?.();
    mouseFireDetach = null;

    keyboardLightToggleDetach?.();
    keyboardLightToggleDetach = null;

    removeLookListeners();
    removeMovementListeners();

    attachedTarget = null;
    resetInputState();
  }

  return {
    attach(target: HTMLElement): InputRouterDetach {
      if (attachedTarget !== null) {
        throw new Error(
          'InputRouter is already attached; detach before re-attaching.',
        );
      }

      attachedTarget = target;
      attachmentId += 1;
      const token = attachmentId;

      pointerLockDetach = bindPointerLock(target);

      mouseFireDetach = bindMouseFire(target, () => {
        pendingFire = true;
      });

      keyboardLightToggleDetach = bindKeyboardLightToggle(window, () => {
        pendingLightToggle = true;
      });

      bindEventListeners();
      bindLookListeners(target);

      return () => detachByToken(token);
    },

    detach(): void {
      detachByToken(attachmentId);
    },

    getSnapshot(): InputSnapshot {
      const pointerLocked =
        typeof document !== 'undefined' &&
        attachedTarget !== null &&
        document.pointerLockElement === attachedTarget;

      const snapshot: InputSnapshot = {
        timestamp: Date.now(),

        movement: {
          forward: keyStates[NEATENSTEIN_KEY_MAP_MOVEMENT.forward] ?? false,
          backward: keyStates[NEATENSTEIN_KEY_MAP_MOVEMENT.backward] ?? false,
          left: keyStates[NEATENSTEIN_KEY_MAP_MOVEMENT.left] ?? false,
          right: keyStates[NEATENSTEIN_KEY_MAP_MOVEMENT.right] ?? false,
        },

        look: {
          yawDelta: mouseYawDelta + touchYawDelta + keyboardYawDelta,
          pitchDelta: mousePitchDelta + touchPitchDelta + keyboardPitchDelta,
        },

        touch: {
          active: touchActive,
          yawDelta: touchYawDelta,
          pitchDelta: touchPitchDelta,
        },

        pointerLocked,

        // Include both latched edge-triggered actions and currently held keys.
        fire: pendingFire || (keyStates[NEATENSTEIN_FIRE_KEY] ?? false),
        dash: pendingDash || (keyStates[NEATENSTEIN_DASH_KEY] ?? false),
        lightToggle: pendingLightToggle,
      };

      // Consume deltas and one-shot actions after snapshot creation.
      pendingFire = false;
      pendingDash = false;
      pendingLightToggle = false;
      mouseYawDelta = 0;
      mousePitchDelta = 0;
      keyboardYawDelta = 0;
      keyboardPitchDelta = 0;
      touchYawDelta = 0;
      touchPitchDelta = 0;

      return snapshot;
    },
  };
}
/**
 * DOM input binding functions for the Neatenstein host game layer.
 *
 * These functions wire pointer-lock mouse look, keyboard arrow-key look, touch
 * drag-to-look, mouse fire, and host-to-worker input forwarding.
 *
 * They are intentionally separate from {@link ../input.ts}: this module owns
 * low-level DOM bindings, while the input router owns authoritative input state
 * and snapshot consumption.
 *
 * @module
 */

import { NEATENSTEIN_INPUT_MESSAGE_TYPE } from '../../constants';
import { type InputSnapshot } from '../input';
import {
  NEATENSTEIN_KEY_MAP_LOOK,
  NEATENSTEIN_KEYBOARD_LOOK_RAD_PER_EVENT,
  NEATENSTEIN_LIGHT_TOGGLE_KEY,
  NEATENSTEIN_MOUSE_SENSITIVITY,
  NEATENSTEIN_POINTER_LOCK_OPTIONS,
  NEATENSTEIN_PRIMARY_MOUSE_BUTTON,
  NEATENSTEIN_TOUCH_DRAG_THRESHOLD_PX,
} from './constants';

/**
 * Look delta produced by mouse, keyboard, or touch bindings.
 *
 * Values are in radians and are signed so callers can add them directly to
 * camera yaw/pitch accumulators.
 */
export interface LookDelta {
  /** Horizontal rotation delta. */
  yawDelta: number;

  /** Vertical rotation delta. */
  pitchDelta: number;
}

/**
 * Callback invoked whenever a look binding emits a new delta.
 */
export type LookCallback = (delta: LookDelta) => void;

/**
 * Callback invoked when the primary fire input is pressed.
 *
 * The central router decides how to latch/consume the event.
 */
export type FireCallback = () => void;

/**
 * Callback invoked when the dynamic light toggle input is pressed.
 *
 * The binding is responsible for the `keydown` edge only; the central router
 * decides whether the toggle is latched or consumed immediately.
 */
export type LightToggleCallback = () => void;

/**
 * Callback invoked when touch look starts or ends tracking an active touch.
 */
export type TouchActiveCallback = (active: boolean) => void;

/**
 * Detaches a previously installed input binding.
 *
 * Detach functions returned by this module are idempotent.
 */
export type BindingDetach = () => void;

/**
 * Find a touch in a `TouchList` by identifier.
 *
 * @param touches - Browser touch list.
 * @param identifier - Identifier to match.
 * @returns Matching touch, or `undefined` if not present.
 */
export function findTouch(
  touches: TouchList,
  identifier: number,
): Touch | undefined {
  for (let index = 0; index < touches.length; index += 1) {
    const touch = touches.item(index);

    if (touch && touch.identifier === identifier) {
      return touch;
    }
  }

  return undefined;
}

/**
 * Return whether an error likely means `PointerLockOptions` is unsupported.
 *
 * Browsers that do not support the options dictionary can throw either a
 * `TypeError` or a DOM-style `NotSupportedError`.
 *
 * @param error - Caught pointer-lock error.
 * @returns Whether retrying without options is appropriate.
 */
function isUnsupportedPointerLockOptionsError(error: unknown): boolean {
  return (
    error instanceof TypeError ||
    (error instanceof Error && error.name === 'NotSupportedError')
  );
}

/**
 * Request pointer lock, retrying without options when needed.
 *
 * Some browsers support pointer lock but not the `unadjustedMovement` options
 * dictionary. This helper first attempts the configured options and then falls
 * back to a plain request when the options are unsupported.
 *
 * @param target - Element requesting pointer lock.
 */
async function requestPointerLockWithFallback(
  target: HTMLElement,
): Promise<void> {
  if (
    typeof document === 'undefined' ||
    typeof target.requestPointerLock !== 'function'
  ) {
    return;
  }

  try {
    await target.requestPointerLock(NEATENSTEIN_POINTER_LOCK_OPTIONS);
    return;
  } catch (error) {
    if (!isUnsupportedPointerLockOptionsError(error)) {
      return;
    }
  }

  try {
    await target.requestPointerLock();
  } catch {
    // Pointer-lock requests can fail if not triggered by a user gesture, denied
    // by browser policy, or blocked by the embedding context. The caller can
    // still provide keyboard/touch fallback controls.
  }
}

/**
 * Request pointer lock on a canvas with raw mouse movement when available.
 *
 * @param canvas - Element that should own pointer lock.
 * @returns Idempotent detach function that removes the click listener and exits
 *   pointer lock if this canvas currently owns it.
 *
 * @example
 * ```ts
 * const unbindPointerLock = bindPointerLock(canvas);
 * unbindPointerLock();
 * ```
 */
export function bindPointerLock(canvas: HTMLElement): BindingDetach {
  let detached = false;

  const requestLock = (): void => {
    void requestPointerLockWithFallback(canvas);
  };

  canvas.addEventListener('click', requestLock);

  return () => {
    if (detached) {
      return;
    }

    detached = true;
    canvas.removeEventListener('click', requestLock);

    if (
      typeof document !== 'undefined' &&
      document.pointerLockElement === canvas &&
      typeof document.exitPointerLock === 'function'
    ) {
      document.exitPointerLock();
    }
  };
}

/**
 * Bind pointer-lock mouse movement to a look callback.
 *
 * Only emits while `document.pointerLockElement === canvas`, so callers receive
 * raw aim deltas only when the player is actively controlling the canvas.
 *
 * @param canvas - Element that owns pointer lock.
 * @param callback - Receives yaw/pitch deltas in radians.
 * @returns Idempotent detach function.
 *
 * @example
 * ```ts
 * const unbind = bindMouseLook(canvas, (delta) => {
 *   camera.yaw += delta.yawDelta;
 * });
 * ```
 */
export function bindMouseLook(
  canvas: HTMLElement,
  callback: LookCallback,
): BindingDetach {
  let detached = false;

  const handleMouseMove = (event: MouseEvent): void => {
    if (detached || document.pointerLockElement !== canvas) {
      return;
    }

    callback({
      yawDelta: event.movementX * NEATENSTEIN_MOUSE_SENSITIVITY,
      pitchDelta: event.movementY * NEATENSTEIN_MOUSE_SENSITIVITY,
    });
  };

  document.addEventListener('mousemove', handleMouseMove);

  return () => {
    if (detached) {
      return;
    }

    detached = true;

    document.removeEventListener('mousemove', handleMouseMove);
  };
}

/**
 * Bind the primary mouse button to a fire callback.
 *
 * Fire activates on `mousedown` for the configured primary button. The binding
 * does not listen for `mouseup`; the input router decides whether fire is
 * edge-triggered, held, or latched.
 *
 * @param target - Element that receives the `mousedown` event.
 * @param callback - Invoked once for each primary-button press.
 * @returns Idempotent detach function.
 *
 * @example
 * ```ts
 * const unbind = bindMouseFire(canvas, () => {
 *   pendingFire = true;
 * });
 * ```
 */
export function bindMouseFire(
  target: HTMLElement,
  callback: FireCallback,
): BindingDetach {
  let detached = false;

  const handleMouseDown = (event: MouseEvent): void => {
    if (detached || event.button !== NEATENSTEIN_PRIMARY_MOUSE_BUTTON) {
      return;
    }

    event.preventDefault();
    callback();
  };

  target.addEventListener('mousedown', handleMouseDown);

  return () => {
    if (detached) {
      return;
    }

    detached = true;
    target.removeEventListener('mousedown', handleMouseDown);
  };
}

/**
 * Bind keyboard arrow keys as fallback look controls.
 *
 * Each arrow-key `keydown` emits a fixed look delta. Repeated keydown events
 * from the browser naturally produce continuous keyboard look while the key is
 * held.
 *
 * @param target - Event target that receives `keydown` events.
 * @param callback - Receives yaw/pitch deltas in radians.
 * @returns Idempotent detach function.
 *
 * @example
 * ```ts
 * const unbind = bindKeyboardLook(window, (delta) => {
 *   camera.yaw += delta.yawDelta;
 * });
 * ```
 */
export function bindKeyboardLook(
  target: HTMLElement | Window,
  callback: LookCallback,
): BindingDetach {
  let detached = false;
  const step = NEATENSTEIN_KEYBOARD_LOOK_RAD_PER_EVENT;

  const keyboardLookDeltaByCode: Record<string, LookDelta> = {
    [NEATENSTEIN_KEY_MAP_LOOK.left]: { yawDelta: -step, pitchDelta: 0 },
    [NEATENSTEIN_KEY_MAP_LOOK.right]: { yawDelta: step, pitchDelta: 0 },
    [NEATENSTEIN_KEY_MAP_LOOK.up]: { yawDelta: 0, pitchDelta: -step },
    [NEATENSTEIN_KEY_MAP_LOOK.down]: { yawDelta: 0, pitchDelta: step },
  };

  const handleKeyDown = (event: KeyboardEvent): void => {
    const delta = keyboardLookDeltaByCode[event.code];

    if (delta !== undefined) {
      event.preventDefault();
      callback(delta);
    }
  };

  target.addEventListener('keydown', handleKeyDown as EventListener);

  return () => {
    if (detached) {
      return;
    }

    detached = true;
    target.removeEventListener('keydown', handleKeyDown as EventListener);
  };
}

/**
 * Bind the configured light-toggle key to a callback.
 *
 * The binding only triggers on the initial `keydown` edge for the exact
 * configured key code. Repeated keydown events from the browser (sent while the
 * key is held) are ignored so the light does not flicker. The binding prevents
 * the default browser action and invokes the supplied callback once per press.
 *
 * @param target - Event target that receives `keydown` events.
 * @param callback - Invoked once for each light-toggle press.
 * @returns Idempotent detach function.
 *
 * @example
 * ```ts
 * const unbind = bindKeyboardLightToggle(window, () => {
 *   state.lightEnabled = !state.lightEnabled;
 * });
 * ```
 */
export function bindKeyboardLightToggle(
  target: HTMLElement | Window,
  callback: LightToggleCallback,
): BindingDetach {
  let detached = false;

  const handleKeyDown = (event: KeyboardEvent): void => {
    if (
      detached ||
      event.code !== NEATENSTEIN_LIGHT_TOGGLE_KEY ||
      event.repeat
    ) {
      return;
    }

    event.preventDefault();
    callback();
  };

  target.addEventListener('keydown', handleKeyDown as EventListener);

  return () => {
    if (detached) {
      return;
    }

    detached = true;
    target.removeEventListener('keydown', handleKeyDown as EventListener);
  };
}

/**
 * Bind touch drag-to-look on a mobile fallback surface.
 *
 * A drag rotates yaw/pitch. The binding stays in a deadzone until cumulative
 * movement exceeds the configured threshold; once engaged, it emits incremental
 * deltas from the last emitted position. On the first emitted delta, that last
 * emitted position is the original touch start, so the threshold-crossing
 * motion is included rather than discarded.
 *
 * @param target - Touch surface.
 * @param callback - Receives yaw/pitch deltas in radians.
 * @param onActive - Optional callback invoked when tracking starts/ends.
 * @returns Idempotent detach function.
 *
 * @example
 * ```ts
 * const unbind = bindTouchLook(overlay, (delta) => {
 *   camera.yaw += delta.yawDelta;
 * });
 * ```
 */
export function bindTouchLook(
  target: HTMLElement,
  callback: LookCallback,
  onActive?: TouchActiveCallback,
): BindingDetach {
  let detached = false;
  let activeTouchId: number | null = null;
  let startX = 0;
  let startY = 0;
  let lastEmittedX = 0;
  let lastEmittedY = 0;
  let engaged = false;

  const threshold = NEATENSTEIN_TOUCH_DRAG_THRESHOLD_PX;

  /**
   * Clear current touch tracking and notify active-state listeners.
   */
  const endActiveTouch = (): void => {
    activeTouchId = null;
    engaged = false;
    onActive?.(false);
  };

  const handleTouchStart = (event: TouchEvent): void => {
    if (detached || activeTouchId !== null) {
      return;
    }

    const touch = event.changedTouches.item(0);

    if (!touch) {
      return;
    }

    event.preventDefault();

    activeTouchId = touch.identifier;
    startX = touch.clientX;
    startY = touch.clientY;
    lastEmittedX = touch.clientX;
    lastEmittedY = touch.clientY;
    engaged = false;

    onActive?.(true);
  };

  const handleTouchMove = (event: TouchEvent): void => {
    if (detached || activeTouchId === null) {
      return;
    }

    const touch = findTouch(event.changedTouches, activeTouchId);

    if (!touch) {
      return;
    }

    event.preventDefault();

    if (!engaged) {
      const cumulativeX = touch.clientX - startX;
      const cumulativeY = touch.clientY - startY;

      if (
        Math.abs(cumulativeX) <= threshold &&
        Math.abs(cumulativeY) <= threshold
      ) {
        return;
      }

      engaged = true;
    }

    const yawDelta =
      (touch.clientX - lastEmittedX) * NEATENSTEIN_MOUSE_SENSITIVITY;
    const pitchDelta =
      (touch.clientY - lastEmittedY) * NEATENSTEIN_MOUSE_SENSITIVITY;

    callback({ yawDelta, pitchDelta });

    lastEmittedX = touch.clientX;
    lastEmittedY = touch.clientY;
  };

  const handleTouchEnd = (event: TouchEvent): void => {
    if (detached || activeTouchId === null) {
      return;
    }

    const touch = findTouch(event.changedTouches, activeTouchId);

    if (touch) {
      event.preventDefault();
      endActiveTouch();
    }
  };

  const handleTouchCancel = (event: TouchEvent): void => {
    if (detached || activeTouchId === null) {
      return;
    }

    const touch = findTouch(event.changedTouches, activeTouchId);

    if (touch) {
      event.preventDefault();
      endActiveTouch();
    }
  };

  const touchListenerOptions: AddEventListenerOptions = { passive: false };

  target.addEventListener('touchstart', handleTouchStart, touchListenerOptions);
  target.addEventListener('touchmove', handleTouchMove, touchListenerOptions);
  target.addEventListener('touchend', handleTouchEnd, touchListenerOptions);
  target.addEventListener(
    'touchcancel',
    handleTouchCancel,
    touchListenerOptions,
  );

  return () => {
    if (detached) {
      return;
    }

    detached = true;

    // Detach removes listeners and silently clears internal tracking state.
    // The active callback reflects only real touch lifecycle events; it must
    // not emit an artificial onActive(false) during teardown.
    activeTouchId = null;
    engaged = false;

    target.removeEventListener(
      'touchstart',
      handleTouchStart,
      touchListenerOptions,
    );
    target.removeEventListener(
      'touchmove',
      handleTouchMove,
      touchListenerOptions,
    );
    target.removeEventListener(
      'touchend',
      handleTouchEnd,
      touchListenerOptions,
    );
    target.removeEventListener(
      'touchcancel',
      handleTouchCancel,
      touchListenerOptions,
    );
  };
}

/**
 * Forward the worker-consumed subset of an input snapshot to the display worker.
 *
 * The worker consumes movement intent, look deltas, fire, dash, and light
 * toggle flags. This helper posts exactly those fields instead of the complete
 * snapshot.
 *
 * @param worker - Dedicated display worker.
 * @param snapshot - Current host input snapshot.
 *
 * @example
 * ```ts
 * const snapshot = router.getSnapshot();
 * forwardWorkerInput(displayWorker, snapshot);
 * ```
 */
export function forwardWorkerInput(
  worker: Worker,
  snapshot: InputSnapshot,
): void {
  worker.postMessage({
    type: NEATENSTEIN_INPUT_MESSAGE_TYPE,
    input: {
      movement: snapshot.movement,
      look: {
        yawDelta: snapshot.look.yawDelta,
        pitchDelta: snapshot.look.pitchDelta,
      },
      fire: snapshot.fire,
      dash: snapshot.dash,
      lightToggle: snapshot.lightToggle,
    },
  });
}
/**
 * Deterministic game-state container for the Neatenstein host-side simulation.
 *
 * This module owns the canonical reset function and the pure state transitions
 * for player damage, ammo consumption, and dash activation. All transitions
 * return a new state object so callers can replay history from a seed without
 * accidental mutation.
 *
 * @module
 */

import seedrandom from 'seedrandom';
import {
  NEATENSTEIN_DASH_COOLDOWN_MS,
  NEATENSTEIN_DASH_INVULNERABILITY_MS,
  NEATENSTEIN_EPISODE_DEFAULT_DURATION_MS,
  NEATENSTEIN_PLAYER_MAX_AMMO,
  NEATENSTEIN_PLAYER_MAX_HEALTH,
  NEATENSTEIN_SPAWN_CENTER_X,
  NEATENSTEIN_SPAWN_CENTER_Y,
} from './constants';
import { NEATENSTEIN_DEFAULT_SEED } from '../../constants';
import { createInitialGunState } from '../../renderer/gun';
import type {
  CreateGameStateOptions,
  EnemyState,
  GameState,
  PlayerState,
} from './types';

/**
 * Reconstruct a seeded PRNG from a deterministic game seed.
 *
 * Callers use this to resume replay after cloning or transferring a plain
 * {@link GameState}. The seed is stored on the state, so the PRNG can always
 * be recreated on demand.
 *
 * @param seed - Deterministic seed originally passed to {@link createGameState}.
 * @returns A seeded PRNG matching the one used at episode start.
 *
 * @example
 * ```ts
 * const rng = createGameRng(state.seed);
 * const nextValue = rng();
 * ```
 */
export function createGameRng(seed: number): () => number {
  return seedrandom(String(seed));
}

/**
 * Build the deterministic initial state for a Neatenstein episode.
 *
 * The same `seed` always produces the same canonical snapshot. The returned
 * object is safe to clone, transfer, and mutate through the pure helpers in
 * this module; deterministic replay reconstructs the PRNG from the stored
 * seed via {@link createGameRng}.
 *
 * @param options - Optional reset configuration; `seed` defaults to
 *   {@link NEATENSTEIN_DEFAULT_SEED}.
 * @returns A fresh canonical {@link GameState} for the requested seed.
 *
 * @example
 * ```ts
 * const state = createGameState({ seed: 7 });
 * expect(state.player.health).toBe(state.player.maxHealth);
 * ```
 */
export function createGameState(
  options: CreateGameStateOptions = {},
): GameState {
  const seed = options.seed ?? NEATENSTEIN_DEFAULT_SEED;
  const rng = createGameRng(seed);
  const spawnPosition = {
    x: NEATENSTEIN_SPAWN_CENTER_X,
    y: NEATENSTEIN_SPAWN_CENTER_Y,
  };
  const player: PlayerState = {
    position: { ...spawnPosition },
    previousPosition: { ...spawnPosition },
    angleRad: rng() * 2 * Math.PI,
    health: NEATENSTEIN_PLAYER_MAX_HEALTH,
    maxHealth: NEATENSTEIN_PLAYER_MAX_HEALTH,
    ammo: NEATENSTEIN_PLAYER_MAX_AMMO,
    maxAmmo: NEATENSTEIN_PLAYER_MAX_AMMO,
    dashTimeRemainingMs: 0,
    dashCooldownMs: 0,
    contactIFrameMs: 0,
  };

  const enemies: EnemyState[] = [];

  return {
    seed,
    simTimeMs: 0,
    episodeTimeMs: 0,
    episodeDurationMs: NEATENSTEIN_EPISODE_DEFAULT_DURATION_MS,
    player,
    enemies,
    impacts: [],
    gun: createInitialGunState(),
    bolts: [],
    enemyBolts: [],
    kills: 0,
    spawnCount: 0,
    generation: 1,
  };
}

/**
 * Check whether the player is currently invulnerable to damage.
 *
 * Invulnerability is granted by a recent dash or by recent enemy contact
 * damage and expires once the corresponding counters reach zero.
 *
 * @param state - Snapshot to inspect.
 * @returns `true` while the player is in an invulnerability window.
 */
export function isInvulnerable(state: GameState): boolean {
  return (
    state.player.dashTimeRemainingMs > 0 ||
    (state.player.contactIFrameMs ?? 0) > 0
  );
}

/**
 * Check whether the player can initiate a new dash.
 *
 * A dash is available only when {@link PlayerState.dashCooldownMs} has reached
 * zero, which happens after the configured cooldown duration.
 *
 * @param state - Snapshot to inspect.
 * @returns `true` if a new dash can be started.
 */
export function canDash(state: GameState): boolean {
  return state.player.dashCooldownMs <= 0;
}

/**
 * Apply damage to the player, clamping health at zero.
 *
 * Damage is ignored while the player is invulnerable (dash i-frames or contact i-frames).
 *
 * @param state - Snapshot before damage.
 * @param amount - Damage amount; clamped to zero if negative.
 * @returns New snapshot with reduced (and clamped) player health, or an
 * immutable clone of the snapshot (with a new player object) if the player is
 * currently invulnerable.
 */
export function applyDamage(state: GameState, amount: number): GameState {
  if (isInvulnerable(state)) {
    return { ...state, player: { ...state.player } };
  }
  const clamped = Math.max(0, amount);
  return {
    ...state,
    player: {
      ...state.player,
      health: Math.max(0, state.player.health - clamped),
    },
  };
}

/**
 * Consume a single unit of ammo.
 *
 * @param state - Snapshot before consumption.
 * @returns New snapshot with ammo decremented by one, clamped at zero.
 */
export function consumeAmmo(state: GameState): GameState {
  return {
    ...state,
    player: {
      ...state.player,
      ammo: Math.max(0, state.player.ammo - 1),
    },
  };
}

/**
 * Activate a dash, granting invulnerability and starting the cooldown.
 *
 * The dash only takes effect when {@link canDash} returns `true`. While on
 * cooldown, an immutable clone of the snapshot (with a new player object) is
 * returned so the observable cooldown prevents indefinite chaining.
 *
 * @param state - Snapshot before the dash.
 * @returns New snapshot with {@link PlayerState.dashTimeRemainingMs} set to the
 * configured invulnerability window and {@link PlayerState.dashCooldownMs} set
 * to the configured cooldown duration, or an immutable clone of the
 * snapshot (with a new player object) while on cooldown.
 */
export function applyDash(state: GameState): GameState {
  if (!canDash(state)) {
    return { ...state, player: { ...state.player } };
  }
  return {
    ...state,
    player: {
      ...state.player,
      dashTimeRemainingMs: NEATENSTEIN_DASH_INVULNERABILITY_MS,
      dashCooldownMs: NEATENSTEIN_DASH_COOLDOWN_MS,
    },
  };
}
/**
 * Pure gun overlay renderer for the Neatenstein neon raycasting demo.
 *
 * The weapon is drawn as a center-screen DOOM-style plasma cannon: a wide
 * Neon White body with a teal energy strip, anchored at the bottom center of
 * the viewport and kicked upward by the current screen-space recoil offset.
 * All rendering is pure side effects on the supplied 2D context.
 *
 * @module
 */

import {
  NEATENSTEIN_GUN_ACCENT_COLOR as GUN_ACCENT_COLOR,
  NEATENSTEIN_GUN_BODY_COLOR as GUN_BODY_COLOR,
} from '../constants';
import type { GunState } from '../host/game/types';
import { GUN_BARREL_VOXEL_GRID, projectGunSprite } from './gun-sprite';

/**
 * CSS color applied to the gun body overlay.
 *
 * A warm near-white ("Neon White") so the weapon reads as painted plastic or
 * ceramic against the dark raycast scene.
 */
export const NEATENSTEIN_GUN_BODY_COLOR = GUN_BODY_COLOR;

/**
 * CSS color applied to gun accent lines and highlights.
 *
 * A bright teal used for energy strips, sight dots, and the matching dynamic
 * light overlay.
 */
export const NEATENSTEIN_GUN_ACCENT_COLOR = GUN_ACCENT_COLOR;

/**
 * Fraction of viewport height occupied by the gun body.
 */
const GUN_BODY_HEIGHT_FRACTION = 0.22;

/**
 * Gun body aspect ratio (width / height).
 *
 * Derived from the chunky DOOM plasma-cannon reference silhouette so the
 * weapon stays square and readable regardless of viewport width.
 */
export const GUN_BODY_ASPECT_RATIO = 0.75;

/**
 * Create the canonical initial {@link GunState} for a fresh episode.
 *
 * The recoil offset starts at zero so the overlay rests in its idle position.
 *
 * @returns A fresh {@link GunState} with zero recoil.
 *
 * @example
 * ```ts
 * const gun = createInitialGunState();
 * expect(gun.recoilOffset).toBe(0);
 * ```
 */
export function createInitialGunState(): GunState {
  return { recoilOffset: 0 };
}

/**
 * Render the gun overlay on top of the raycast frame.
 *
 * The gun is anchored at the bottom center of the viewport. When
 * {@link GunState.recoilOffset} is non-zero, the entire overlay is translated
 * upward by that amount before drawing, producing a visible kick that settles
 * back to the idle position as the recoil decays.
 *
 * The sprite is drawn as a chunky DOOM-style plasma cannon: a tapered Neon
 * White body, a glowing central energy core, and teal accent bolts.
 *
 * @param ctx - 2D canvas context to draw into.
 * @param gun - Current weapon overlay state.
 * @param width - Viewport width in CSS pixels.
 * @param height - Viewport height in CSS pixels.
 *
 * @example
 * ```ts
 * const gun = createInitialGunState();
 * renderGunOverlay(ctx, gun, 640, 360);
 * ```
 */
export function renderGunOverlay(
  ctx: CanvasRenderingContext2D | OffscreenCanvasRenderingContext2D,
  gun: GunState,
  width: number,
  height: number,
): void {
  const centerX = width / 2;
  const gunBottomY = height;
  const gunHeight = height * GUN_BODY_HEIGHT_FRACTION;
  const gunWidth = gunHeight * GUN_BODY_ASPECT_RATIO;
  const gunTop = gunBottomY - gunHeight;

  ctx.save();
  if (gun.recoilOffset !== 0) {
    ctx.translate(0, -gun.recoilOffset);
  }

  // Tapered main chassis with a left-to-right plastic shading gradient.
  const baseHalfWidth = gunWidth / 2;
  const topHalfWidth = gunWidth * 0.33;

  const chassisGradient = ctx.createLinearGradient(
    centerX - baseHalfWidth,
    gunTop,
    centerX + baseHalfWidth,
    gunTop,
  );
  chassisGradient.addColorStop(0, '#c8d4d8');
  chassisGradient.addColorStop(0.25, '#eefcfd');
  chassisGradient.addColorStop(0.5, '#ffffff');
  chassisGradient.addColorStop(0.75, '#eefcfd');
  chassisGradient.addColorStop(1, '#b8c4c8');

  ctx.fillStyle = chassisGradient;
  ctx.beginPath();
  ctx.moveTo(centerX - baseHalfWidth, gunBottomY);
  ctx.lineTo(centerX - topHalfWidth, gunTop);
  ctx.lineTo(centerX + topHalfWidth, gunTop);
  ctx.lineTo(centerX + baseHalfWidth, gunBottomY);
  ctx.closePath();
  ctx.fill();

  // Left and right 3D side planes so the cannon reads as an extruded voxel
  // body rather than a flat gradient shape.
  const sidePanelInset = baseHalfWidth * 0.55;
  const topSideInset = topHalfWidth * 0.45;

  // Darker left face.
  ctx.fillStyle = '#8fa0a5';
  ctx.beginPath();
  ctx.moveTo(centerX - baseHalfWidth, gunBottomY);
  ctx.lineTo(centerX - topHalfWidth, gunTop);
  ctx.lineTo(centerX - topHalfWidth + topSideInset, gunTop);
  ctx.lineTo(centerX - baseHalfWidth + sidePanelInset, gunBottomY);
  ctx.closePath();
  ctx.fill();

  // Lighter right face.
  ctx.fillStyle = '#d8eef2';
  ctx.beginPath();
  ctx.moveTo(centerX + baseHalfWidth, gunBottomY);
  ctx.lineTo(centerX + topHalfWidth, gunTop);
  ctx.lineTo(centerX + topHalfWidth - topSideInset, gunTop);
  ctx.lineTo(centerX + baseHalfWidth - sidePanelInset, gunBottomY);
  ctx.closePath();
  ctx.fill();

  // Accent outline around the chassis.
  ctx.lineWidth = Math.max(1, width * 0.002);
  ctx.strokeStyle = NEATENSTEIN_GUN_ACCENT_COLOR;
  ctx.stroke();

  // Central plasma core, tapered to match the gun body's perspective.
  const coreWidthTop = gunWidth * 0.16;
  const coreWidthBottom = gunWidth * 0.3;
  const coreHeight = gunHeight * 0.72;
  const coreTop = gunTop + gunHeight * 0.08;
  const coreBottom = coreTop + coreHeight;
  const coreLeftTop = centerX - coreWidthTop / 2;
  const coreRightTop = centerX + coreWidthTop / 2;
  const coreLeftBottom = centerX - coreWidthBottom / 2;
  const coreRightBottom = centerX + coreWidthBottom / 2;
  const coreGradient = ctx.createLinearGradient(
    coreLeftBottom,
    coreTop,
    coreRightBottom,
    coreTop,
  );
  coreGradient.addColorStop(0, '#008b9a');
  coreGradient.addColorStop(0.4, NEATENSTEIN_GUN_ACCENT_COLOR);
  coreGradient.addColorStop(0.6, '#80f8ff');
  coreGradient.addColorStop(1, '#006b7a');

  ctx.fillStyle = coreGradient;
  ctx.beginPath();
  ctx.moveTo(coreLeftBottom, coreBottom);
  ctx.lineTo(coreLeftTop, coreTop);
  ctx.lineTo(coreRightTop, coreTop);
  ctx.lineTo(coreRightBottom, coreBottom);
  ctx.closePath();
  ctx.fill();

  // Lower teal accent bolts on each side.
  ctx.fillStyle = NEATENSTEIN_GUN_ACCENT_COLOR;
  for (const side of [-1, 1] as const) {
    for (const ridgeY of [gunTop + gunHeight * 0.55 + height * 0.015]) {
      ctx.beginPath();
      ctx.arc(
        centerX + side * baseHalfWidth * 0.84,
        ridgeY,
        width * 0.004,
        0,
        Math.PI * 2,
      );
      ctx.fill();
    }
  }

  // Raised barrel band near the muzzle.
  ctx.fillStyle = '#c8d4d8';
  const bandY = gunTop + gunHeight * 0.18;
  const bandHeight = gunHeight * 0.05;
  const bandWidth = gunWidth * 0.92;
  ctx.fillRect(centerX - bandWidth / 2, bandY, bandWidth, bandHeight);

  // Dark side-vent slits on the lower chassis.
  ctx.fillStyle = '#4a5a5e';
  const ventWidth = gunWidth * 0.08;
  const ventHeight = gunHeight * 0.08;
  const ventY = gunTop + gunHeight * 0.62;
  for (const side of [-1, 1] as const) {
    ctx.fillRect(
      centerX + side * baseHalfWidth * 0.72 - ventWidth / 2,
      ventY,
      ventWidth,
      ventHeight,
    );
  }

  // Teal top sight post above the muzzle.
  ctx.fillStyle = NEATENSTEIN_GUN_ACCENT_COLOR;
  const sightWidth = gunWidth * 0.14;
  const sightHeight = gunHeight * 0.06;
  ctx.fillRect(
    centerX - sightWidth / 2,
    gunTop - sightHeight * 0.7,
    sightWidth,
    sightHeight,
  );

  // Project a small 3D voxel barrel above the main chassis.
  const barrelScale = gunHeight * 0.05;
  const barrelBaseY = gunTop - gunHeight * 0.02;
  const projectedVoxels = projectGunSprite({
    voxelGrid: GUN_BARREL_VOXEL_GRID,
    screenX: centerX,
    screenY: barrelBaseY,
    scale: barrelScale,
  });
  for (const voxel of projectedVoxels) {
    ctx.fillStyle = voxel.color;
    ctx.fillRect(
      voxel.screenX - voxel.size / 2,
      voxel.screenY - voxel.size / 2,
      voxel.size,
      voxel.size,
    );
  }

  ctx.restore();
}
/**
 * Host-side renderer bridge for the Neatenstein neon raycasting demo.
 *
 * This module owns the boundary between the main browser thread and the
 * display worker. It is responsible for:
 *
 * - spawning the module worker,
 * - forwarding the host-derived render size to the worker without constraints,
 * - transferring an {@link OffscreenCanvas} on the `worker` tier,
 * - forwarding simulation state to the worker,
 * - forwarding input snapshots to the worker,
 * - exposing the latest rendered frame request id for CPU/GPU tiers,
 * - and terminating the worker on teardown.
 *
 * The bridge intentionally remains thin; it forwards the host-provided canvas
 * backing-store dimensions because this is the last host-side boundary before
 * the worker owns direct rendering.
 *
 * @module
 */

import {
  NEATENSTEIN_INPUT_MESSAGE_TYPE,
  NEATENSTEIN_RENDER_FRAME_FORMAT_VERSION,
  NEATENSTEIN_WORKER_BUNDLE_FILENAME,
  type NeatensteinTier,
} from '../constants';
import type {
  NeatensteinRenderFrame,
  NeatensteinRenderState,
} from '../renderer/frame';
import type { InputSnapshot } from './input';

/**
 * Default worker bundle URL used when the caller does not supply one.
 */
const DEFAULT_WORKER_URL = `/assets/${NEATENSTEIN_WORKER_BUNDLE_FILENAME}`;

/**
 * Configuration needed to create a host side renderer bridge that spawns the
 * display worker and transfers the OffscreenCanvas to the selected tier.
 */
export interface NeatensteinRendererBridgeOptions {
  /** The visible canvas element on the host page. */
  canvas: HTMLCanvasElement;
  /** Absolute or relative URL to the worker bundle. */
  workerUrl?: string;
  /** Selected renderer tier. */
  tier: NeatensteinTier;
  /** Deterministic seed used to build the wall grid on the worker. */
  mapSeed: number;
}

/**
 * Public surface of the host renderer bridge that callers use to forward
 * state, send input, and consume rendered frames from the display worker.
 */
export interface NeatensteinRendererBridge {
  /** The spawned display worker. */
  worker: Worker;
  /** Latest frame request id received from the worker. */
  requestId: number;
  /** Forward a simulation state snapshot to the worker. The bridge applies
   * worker-busy backpressure so only one snapshot is in flight at a time;
   * additional calls defer the latest state until the worker acknowledges. */
  postSimState(state: NeatensteinRenderState): void;
  /** Forward a host-resized CSS-box dimension to the worker. */
  resize(width: number, height: number): void;
  /** Forward an input snapshot to the worker so it can advance the sim tick. */
  forwardWorkerInput(snapshot: InputSnapshot): void;
  /** Terminate the worker and release the bridge. */
  destroy(): void;
  /**
   * Register a callback that receives every rendered frame produced by the
   * worker on the `cpu` and `gpu` tiers.
   *
   * The consumer is called synchronously when a `frame` message arrives, before
   * the bridge updates its latest request id. This lets the host overlay or
   * capture pipeline consume the same frame payload without an extra copy.
   *
   * @param consumer - Function invoked with each incoming render frame.
   */
  setFrameConsumer(consumer: (frame: NeatensteinRenderFrame) => void): void;
  /**
   * Register a callback invoked when the worker finishes rendering a frame
   * and has no pending state to flush. The host uses this to schedule the
   * next `requestAnimationFrame`, making the render loop purely worker-paced
   * instead of running continuously at display refresh rate.
   *
   * The callback is NOT called when a deferred `pendingState` is flushed on
   * the frame ack — the flushed state's own ack will trigger it once the
   * worker finishes that render.
   *
   * Pass `null` to clear the callback.
   *
   * @param callback - Function invoked when the worker is idle and ready for
   *   the next frame, or `null` to clear.
   */
  setOnFrameReady(callback: (() => void) | null): void;
}

/**
 * Return whether a value is usable as a positive render dimension.
 *
 * @param value - Candidate dimension.
 * @returns Whether the value is finite and positive.
 */
function isPositiveFiniteDimension(value: number): boolean {
  return Number.isFinite(value) && value > 0;
}

/**
 * Resolve the initial canvas dimensions the bridge forwards to the worker.
 *
 * The bridge prefers the canvas backing-store dimensions because the host
 * browser entry already set them to the fixed 480px-height, viewport-aspect-ratio
 * size. If those are unavailable, it falls back to layout dimensions.
 *
 * @param canvas - Visible host canvas.
 * @returns A dimension pair, or `null` if no usable dimensions exist.
 */
function resolveInitialCanvasRenderSize(
  canvas: HTMLCanvasElement,
): { width: number; height: number } | null {
  const backingWidth = canvas.width;
  const backingHeight = canvas.height;

  if (
    isPositiveFiniteDimension(backingWidth) &&
    isPositiveFiniteDimension(backingHeight)
  ) {
    return { width: backingWidth, height: backingHeight };
  }

  if (
    isPositiveFiniteDimension(canvas.clientWidth) &&
    isPositiveFiniteDimension(canvas.clientHeight)
  ) {
    return { width: canvas.clientWidth, height: canvas.clientHeight };
  }

  return null;
}

/**
 * Return whether a value looks like a worker protocol message object.
 *
 * @param value - Raw message payload.
 * @returns Whether the value can be inspected as a message record.
 */
function isMessageRecord(value: unknown): value is Record<string, unknown> {
  return Boolean(value) && typeof value === 'object';
}

/**
 * Create and initialize a host-side bridge to the Neatenstein display worker.
 *
