  worker.postMessage(
    {
      type: 'init',
      tier,
      version: NEATENSTEIN_RENDER_FRAME_FORMAT_VERSION,
      mapSeed,
      ...(initialRenderSize
        ? {
            canvasWidth: initialRenderSize.width,
            canvasHeight: initialRenderSize.height,
