(function loadNeatensteinBundle() {
  const statusElement = document.getElementById('status');
  if (statusElement) {
    statusElement.textContent = 'Loading Neatenstein...';
  }
  const bundleSrc = '/docs/assets/neatenstein.bundle.js?v=20260802-7';
  const scriptElement = document.createElement('script');

  scriptElement.src = bundleSrc;
  scriptElement.defer = true;
  scriptElement.onload = function () {
    if (window.neatensteinStart) {
      window.neatensteinStart('neatenstein-output', 'neatenstein-canvas');
      if (statusElement) {
        statusElement.textContent = '';
      }
      return;
    }
    if (statusElement) {
      statusElement.textContent =
        'Bundle loaded, but no Neatenstein start function was found.';
    }
  };
  scriptElement.onerror = function () {
    if (statusElement) {
      statusElement.textContent =
        'Failed to load neatenstein.bundle.js from ' + bundleSrc;
    }
  };
  document.body.appendChild(scriptElement);
})();

